#[test]
fn golden_vectors_have_the_documented_shapes() {
    assert_eq!(DLY_CTX_IN.len(), 70);
    assert_eq!(DLY_CTX_OUT.len(), DLY_CTX_IN.len());
    assert_eq!(DLY_FRAMES_IN.len(), 12);
    assert_eq!(DLY_FRAMES_OUT.len(), DLY_FRAMES_IN.len());
    assert!(DLY_FRAMES_IN != DLY_FRAMES_OUT);
}
